#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立实现：max_element 求最大值（并列取下标最大者：从后往前找），min 取非零最小
static int expected(vector<int> a) {
    int cnt = 0;
    for (;;) {
        int mxv = *max_element(a.begin(), a.end());
        if (mxv == 0) break;
        int k = (int)a.size() - 1;
        while (k >= 0 && a[k] != mxv) --k;
        int mn = mxv;
        for (int v : a) if (v > 0) mn = min(mn, v);
        a[k] -= mn;
        ++cnt;
    }
    return cnt;
}

static bool check(const string& exe, const vector<int>& a, int id, int hard) {
    const string inFile = "l3a09p1_input.txt", outFile = "l3a09p1_output.txt";
    {
        ofstream out(inFile);
        out << a.size() << '\n';
        for (size_t i = 0; i < a.size(); ++i) out << a[i] << (i + 1 == a.size() ? '\n' : ' ');
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    istringstream parser(output);
    int actual = -1;
    string extra;
    const int want = hard >= 0 ? hard : expected(a);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << a.size() << ", expected=" << want
             << ", actual=" << output.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    // 自检：独立实现必须与 PDF 两个样例一致
    if (expected({2, 3, 4}) != 7 || expected({1, 3, 2, 2, 5}) != 13) {
        cout << "[FAIL] self-check: expected() disagrees with PDF samples\n";
        return 1;
    }
    vector<vector<int>> tests = {
        {2, 3, 4}, {1, 3, 2, 2, 5},
        {0}, {100}, {1, 1}, {5, 5, 5},
        {2, 3, 4, 0}, {100, 0, 100}, {7},
    };
    vector<int> hard = {7, 13, -1, -1, -1, -1, -1, -1, -1};
    unsigned seed = 202509u;
    for (int trial = 0; trial < 8; ++trial) {
        int n = trial == 7 ? 100 : 1 + trial * 13;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            seed = seed * 1664525u + 1013904223u;
            a[i] = static_cast<int>(seed % 101u);
        }
        tests.push_back(a);
        hard.push_back(-1);
    }
    tests.push_back(vector<int>(100, 100)); hard.push_back(100);
    tests.push_back(vector<int>(100, 0));   hard.push_back(0);
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1), hard[i])) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

