#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>
using namespace std;

// 独立实现：以 2025-01-01（星期三）为锚点累加各月天数推 m 月 1 日星期几（1=周一..7=周日）
static string expected(int m) {
    static const int days[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int offset = 0;
    for (int i = 1; i < m; ++i) offset += days[i];
    int w = (2 + offset) % 7 + 1;
    string out = "MON TUE WED THU FRI SAT SUN\n";
    for (int i = 1; i < w; ++i) out += "    ";
    for (int i = 1; i <= days[m]; ++i) {
        char buf[16];
        sprintf(buf, "% 3d", i);
        out += buf;
        w = w % 7 + 1;
        if (w == 1 || i == days[m]) out += "\n";
        else out += " ";
    }
    return out;
}

static string show(const string& s) {
    string r;
    for (char c : s) {
        if (c == '\n') r += "|";
        else if (c == ' ') r += ".";
        else r += c;
    }
    return r;
}

static bool check(const string& exe, int m, int id) {
    const string inFile = "l3a09p2_input.txt", outFile = "l3a09p2_output.txt";
    { ofstream out(inFile); out << m << '\n'; }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    string norm;
    for (size_t i = 0; i < output.size(); ++i) {
        if (output[i] == '\r' && i + 1 < output.size() && output[i + 1] == '\n') continue;
        norm += output[i];
    }
    const string want = expected(m);
    bool ok = code == 0 && norm == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": m=" << m << "\n  expected=" << show(want)
             << "\n  actual=" << show(norm) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    // 自检：独立实现必须 reproduces PDF 两个样例的版式（9 月首行、6 月首行 24 空格前缀）
    if (expected(9).find("  1   2   3   4   5   6   7\n") == string::npos ||
        expected(6).find(string(24, ' ') + "  1\n") == string::npos) {
        cout << "[FAIL] self-check: expected() disagrees with PDF sample layout\n";
        return 1;
    }
    int pass = 0;
    const int total = 12;
    for (int m = 1; m <= total; ++m)
        if (check(argv[1], m, m)) ++pass;
    cout << "Results: " << pass << "/" << total << " passed\n";
    return pass == total ? 0 : 1;
}
